<?php
require_once __DIR__.'/functions.php'; require_once __DIR__.'/app_init.php'; require_login(); $pdo=dogvive_db();
if($_SERVER['REQUEST_METHOD']==='POST'){
 try { if(current_role()!=='Propietario') throw new RuntimeException('Solo los propietarios pueden solicitar servicios.'); $sid=(int)($_POST['id_servicio']??0); $petid=(int)($_POST['id_mascota']??0); $trainer=(int)($_POST['id_entrenador']??0); $date=(string)($_POST['fecha']??''); $time=(string)($_POST['hora']??''); $desc=trim((string)($_POST['descripcion']??''));
 $s=$pdo->prepare('SELECT id_servicio,Nombre FROM servicio WHERE id_servicio=?'); $s->execute([$sid]); $service=$s->fetch(); if(!$service) throw new RuntimeException('Selecciona un servicio válido.'); $p=$pdo->prepare('SELECT id_mascota,Nombre FROM mascota WHERE id_mascota=? AND id_usuario=?'); $p->execute([$petid,dogvive_user_id()]); $pet=$p->fetch(); if(!$pet) throw new RuntimeException('Selecciona una mascota registrada en tu cuenta.'); if(!$date||$date<date('Y-m-d')||!preg_match('/^\d{2}:\d{2}$/',$time)) throw new RuntimeException('Selecciona una fecha futura y una hora válida.'); if($trainer){$t=$pdo->prepare("SELECT id_usuario FROM usuario WHERE id_usuario=? AND Tipo_usuario IN ('Entrenador','entrenador')");$t->execute([$trainer]);if(!$t->fetch())throw new RuntimeException('El entrenador seleccionado no es válido.');} else $trainer=null;
 $ins=$pdo->prepare('INSERT INTO reserva (Fecha,Hora,Estado,id_usuario,id_servicio,id_mascota,id_entrenador,Descripcion) VALUES (?,?,?,?,?,?,?,?)'); $ins->execute([$date,$time,'Pendiente',dogvive_user_id(),$sid,$petid,$trainer,$desc]); $rid=(int)$pdo->lastInsertId(); dogvive_notice($pdo,dogvive_user_id(),'Reserva','Tu solicitud para '.$pet['Nombre'].' fue registrada y está pendiente de confirmación.','reservas.php'); if($trainer) dogvive_notice($pdo,$trainer,'Nueva reserva','Tienes una nueva solicitud de entrenamiento.','reservas.php'); dogvive_flash('success','Solicitud guardada correctamente. Puedes consultar su estado en Mis reservas.'); header('Location: '.base_url().'/reservas.php'); exit;
 }catch(Throwable $e){dogvive_flash('error',$e instanceof RuntimeException?$e->getMessage():'No se pudo guardar la solicitud. Verifica que existan servicios en la base de datos.');header('Location: '.base_url().'/solicitud-servicio.php');exit;}
}
$preferredTrainer=(int)($_GET['entrenador']??0); $services=$pdo->query('SELECT id_servicio,Nombre,Descripcion,Precio,Duracion FROM servicio ORDER BY Nombre')->fetchAll(); $pets=$pdo->prepare('SELECT id_mascota,Nombre,Especie,Raza FROM mascota WHERE id_usuario=? ORDER BY Nombre'); $pets->execute([dogvive_user_id()]); $pets=$pets->fetchAll(); $trainers=$pdo->query("SELECT id_usuario,Nombre,Apellido,Especialidad FROM usuario WHERE LOWER(Tipo_usuario)='entrenador' ORDER BY Nombre")->fetchAll();
start_app('Solicitar servicio','solicitud-servicio'); page_wrap_start('Solicitar entrenamiento','Elige servicio, mascota, entrenador y horario.'); $error=dogvive_flash('error'); if($error)echo '<div class="error-box">'.e($error).'</div>';
if(current_role()!=='Propietario') echo '<div class="notice">Esta función está disponible para cuentas de propietario.</div>'; elseif(!$pets) echo '<div class="card"><p>Primero registra una mascota para poder solicitar una sesión.</p>'.btn('Registrar mascota',page_url('registro-mascota'),'btn-primary').'</div>'; elseif(!$services) echo '<div class="card"><p>Aún no hay servicios disponibles en la base de datos. Agrega servicios a la tabla servicio desde phpMyAdmin.</p></div>'; else { ?>
<div class="form-box card" style="max-width:850px"><form method="post"><label>Servicio<select name="id_servicio" required><option value="">Selecciona un servicio</option><?php foreach($services as $s): ?><option value="<?= (int)$s['id_servicio'] ?>"><?= e($s['Nombre']) ?> — $<?= number_format((float)$s['Precio'],0,',','.') ?> / <?= (int)$s['Duracion'] ?> min</option><?php endforeach; ?></select></label><label>Mascota<select name="id_mascota" required><option value="">Selecciona una mascota</option><?php foreach($pets as $p): ?><option value="<?= (int)$p['id_mascota'] ?>"><?= e($p['Nombre'].' · '.$p['Especie'].' '.$p['Raza']) ?></option><?php endforeach; ?></select></label><label>Entrenador (opcional)<select name="id_entrenador"><option value="0">Que me asignen uno</option><?php foreach($trainers as $t): ?><option value="<?= (int)$t['id_usuario'] ?>" <?= $preferredTrainer===(int)$t['id_usuario']?'selected':'' ?>><?= e(trim($t['Nombre'].' '.$t['Apellido']).' · '.$t['Especialidad']) ?></option><?php endforeach; ?></select></label><div class="form-grid"><label>Fecha deseada<input type="date" name="fecha" min="<?= date('Y-m-d') ?>" required></label><label>Hora deseada<input type="time" name="hora" required></label></div><label>¿Qué necesitas trabajar?<textarea name="descripcion" rows="4" maxlength="2000" placeholder="Cuéntanos el objetivo o comportamiento que quieres mejorar"></textarea></label><button class="btn btn-primary full" type="submit">Enviar solicitud</button></form></div><?php }
page_wrap_end(); end_app();
